"use client";

import React, { useState } from "react";
import * as LucideIcons from "lucide-react";
import { Button } from "../../../components/ui/Button";

// Safe icon renderer
function Icon({ name, className }: { name: string, className?: string }) {
    const LucideIcon = (LucideIcons as any)[name];
    if (!LucideIcon) return <div className={className} style={{ width: '20px', height: '20px', backgroundColor: '#333', borderRadius: '4px' }} />;
    return <LucideIcon className={className} />;
}

export default function AdminEstoque() {
    const [inventory] = useState([
        { id: 1, product: "Pomada Modeladora Premium", category: "Finalizadores", stock: 15, min: 5, price: "R$ 45,00" },
        { id: 2, product: "Shampoo para Barba 200ml", category: "Higiene", stock: 8, min: 10, price: "R$ 38,00" },
        { id: 3, product: "Óleo Essencial Sândalo", category: "Cuidados", stock: 12, min: 5, price: "R$ 52,00" },
        { id: 4, product: "Lâmina Descartável (CX 100)", category: "Consumíveis", stock: 45, min: 20, price: "R$ 15,00" },
        { id: 5, product: "Cera de Bigode", category: "Finalizadores", stock: 3, min: 5, price: "R$ 25,00" },
    ]);

    return (
        <div className="min-h-screen bg-[#0a0a0a] text-white p-6 lg:p-12 font-sans selection:bg-[#D4AF37] selection:text-black animate-fade-in-up">
            <header className="mb-10 lg:mb-12 flex flex-col md:flex-row md:items-center justify-between gap-6">
                <div>
                    <h1 className="text-3xl font-semibold mb-1">
                        Gestão de <span className="text-[#D4AF37]">Estoque</span>
                    </h1>
                    <p className="text-gray-400 text-sm">Controle de produtos para uso e revenda</p>
                </div>
                <Button className="gap-2">
                    <Icon name="Plus" className="w-4 h-4" /> Novo Produto
                </Button>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-12">
                {[
                    { label: "Itens Cadastrados", value: "24", icon: "Boxes" },
                    { label: "Abaixo do Mínimo", value: "3", icon: "AlertTriangle", color: "text-red-500" },
                    { label: "Valor em Estoque", value: "R$ 4.850", icon: "DollarSign" },
                ].map((stat, i) => (
                    <div key={i} className="bg-[#111111] border border-[#1f1f1f] p-6 rounded-2xl flex items-center gap-6">
                        <div className={`bg-[#D4AF37]/5 w-12 h-12 rounded-xl flex items-center justify-center ${stat.color || 'text-[#D4AF37]'}`}>
                            <Icon name={stat.icon} className="w-6 h-6" />
                        </div>
                        <div>
                            <p className="text-gray-500 text-[10px] uppercase font-bold tracking-widest">{stat.label}</p>
                            <h3 className="text-xl font-bold tracking-tight">{stat.value}</h3>
                        </div>
                    </div>
                ))}
            </div>

            <div className="bg-[#111111] border border-[#1f1f1f] rounded-2xl overflow-hidden">
                <table className="w-full text-left">
                    <thead>
                        <tr className="border-b border-[#1f1f1f] bg-[#161616]">
                            <th className="p-5 text-[10px] uppercase tracking-widest text-gray-500 font-bold">Produto</th>
                            <th className="p-5 text-[10px] uppercase tracking-widest text-gray-500 font-bold">Categoria</th>
                            <th className="p-5 text-[10px] uppercase tracking-widest text-gray-500 font-bold">Qtd. Atual</th>
                            <th className="p-5 text-[10px] uppercase tracking-widest text-gray-500 font-bold">Preço Unit.</th>
                            <th className="p-5 text-[10px] uppercase tracking-widest text-gray-500 font-bold text-center">Ações</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-[#1f1f1f]">
                        {inventory.map((item) => (
                            <tr key={item.id} className="hover:bg-white/[0.01] transition-all group">
                                <td className="p-5">
                                    <p className="font-bold text-sm">{item.product}</p>
                                </td>
                                <td className="p-5">
                                    <span className="text-[9px] uppercase font-black text-gray-500 bg-[#0a0a0a] px-2 py-1 rounded border border-[#1f1f1f]">
                                        {item.category}
                                    </span>
                                </td>
                                <td className="p-5">
                                    <div className="flex items-center gap-3">
                                        <span className={`font-bold text-base ${item.stock <= item.min ? 'text-red-500' : 'text-emerald-500'}`}>
                                            {item.stock}
                                        </span>
                                        {item.stock <= item.min && (
                                            <Icon name="AlertCircle" className="w-4 h-4 text-red-500 animate-pulse" />
                                        )}
                                    </div>
                                </td>
                                <td className="p-5 text-[#D4AF37] font-bold">{item.price}</td>
                                <td className="p-5">
                                    <div className="flex justify-center gap-3">
                                        <button className="p-2 hover:bg-[#D4AF37]/10 rounded-lg text-gray-400 hover:text-[#D4AF37] transition-all"><Icon name="PackagePlus" className="w-4 h-4" /></button>
                                        <button className="p-2 hover:bg-white/5 rounded-lg text-gray-400 hover:text-white transition-all"><Icon name="Edit3" className="w-4 h-4" /></button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}
